// ===== CFG — edit these =====
const CFG = {
  NICOLE: '+14849398535',            // rings first, gets alerts
  NICK:   '+14848418501',            // gets alerts too
  RING_SECONDS: 20,
  BUSINESS: 'D N E Contracting',
  SUPA_URL: 'https://qgbjiqdwzgkjkmqyjsmc.supabase.co',
  SUPA_KEY: 'PASTE_SERVICE_KEY',      // Supabase service_role key (n8n only)
  TWILIO_SID: 'PASTE_TWILIO_ACCOUNT_SID',
};
// ============================
const b = $json.body || $json;
const s = (v, n) => (typeof v === 'string' ? v.trim().slice(0, n || 200) : '');
const from = s(b.From), to = s(b.To), sid = s(b.CallSid), fwd = s(b.ForwardedFrom);
const city = [s(b.FromCity), s(b.FromState)].filter(Boolean).join(', ');
const here = $('Call comes in').first().json.webhookUrl || '';
const root = here.replace(/\/dne-voice-3f8a1c7e2b94.*$/, '');
const statusUrl = root + '/dne-dial-5c2d9e4f7a16';
const vmUrl = root + '/dne-vm-8e1b6d3c4f52';

// A call forwarded from Nicole's cell already rang her — go straight to missed-call handling.
if (fwd) {
  return [{ json: { mode: 'missed', from, to, sid, city, fwd, cfg: CFG, vmUrl, twiml: null } }];
}
// Otherwise ring Nicole, caller ID = the caller, and report back to the dial-status webhook.
const twiml = `<?xml version="1.0" encoding="UTF-8"?><Response><Dial timeout="${CFG.RING_SECONDS}" callerId="${from}" action="${statusUrl}" method="POST"><Number>${CFG.NICOLE}</Number></Dial></Response>`;
return [{ json: { mode: 'ring', from, to, sid, city, cfg: CFG, vmUrl, twiml } }];

// Twilio tells us how the <Dial> to Nicole went.
const CFG = { NICOLE: '+14849398535', NICK: '+14848418501', BUSINESS: 'D N E Contracting', SUPA_URL: 'https://qgbjiqdwzgkjkmqyjsmc.supabase.co', SUPA_KEY: 'PASTE_SERVICE_KEY', TWILIO_SID: 'PASTE_TWILIO_ACCOUNT_SID' };
const b = $json.body || $json;
const s = (v, n) => (typeof v === 'string' ? v.trim().slice(0, n || 200) : '');
const status = s(b.DialCallStatus);
const here = $('Dial result').first().json.webhookUrl || '';
const vmUrl = here.replace(/\/dne-dial-5c2d9e4f7a16.*$/, '') + '/dne-vm-8e1b6d3c4f52';
const answered = status === 'completed' || status === 'answered';
return [{ json: { mode: answered ? 'answered' : 'missed', status, from: s(b.From), to: s(b.To), sid: s(b.CallSid), city: [s(b.FromCity), s(b.FromState)].filter(Boolean).join(', '), cfg: CFG, vmUrl } }];

// Build the three texts + the log row for a missed call. Works for both entry points.
const d = $json; const C = d.cfg;
const who = d.from + (d.city ? ' (' + d.city + ')' : '');
const when = new Date().toLocaleString('en-US', { timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit', month: 'short', day: 'numeric' });
const callerText = `Hi, this is Nicole at ${C.BUSINESS} — sorry I missed your call! Text me what you're thinking about (kitchen, bath, basement, or a repair) and I'll get right back to you. No pressure, nothing to decide today. Or call back any time.`;
const alertText = `MISSED CALL ${who} · ${when}${d.fwd ? ' (forwarded from your cell)' : ''}. They were texted back. Call: ${d.from}`;
return [
  { json: { to: d.from, body: callerText, kind: 'caller', ctx: d } },
  { json: { to: C.NICOLE, body: alertText, kind: 'nicole', ctx: d } },
  { json: { to: C.NICK, body: alertText, kind: 'nick', ctx: d } },
];

// Log once (first item carries the context) and hand back the voicemail TwiML.
const d = $('Write texts').first().json.ctx; const C = d.cfg;
return [{ json: {
  url: C.SUPA_URL + '/rest/v1/dne_missed_calls', apikey: C.SUPA_KEY,
  payload: { call_sid: d.sid, caller: d.from, caller_city: d.city || null, forwarded_from: d.fwd || null, dial_status: d.status || null, texted_caller: true, alerted: ['nicole','nick'] },
  twiml: `<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="Polly.Joanna">Hi, you've reached D N E Contracting. Sorry we missed you — we just sent you a text so you can reply whenever is easy. Or leave a message after the tone and Nicole will call you back.</Say><Record maxLength="120" playBeep="true" transcribe="true" transcribeCallback="${d.vmUrl}"/><Say voice="Polly.Joanna">Thanks, talk soon.</Say></Response>`
} }];

const CFG = { NICOLE: '+14849398535', NICK: '+14848418501', SUPA_URL: 'https://qgbjiqdwzgkjkmqyjsmc.supabase.co', SUPA_KEY: 'PASTE_SERVICE_KEY', TWILIO_SID: 'PASTE_TWILIO_ACCOUNT_SID' };
const b = $json.body || $json;
const s = (v, n) => (typeof v === 'string' ? v.trim().slice(0, n || 200) : '');
const text = s(b.TranscriptionText, 900) || '(no words detected)';
const from = s(b.From), sid = s(b.CallSid), rec = s(b.RecordingUrl, 400);
const body = `VOICEMAIL from ${from}: "${text}"` + (rec ? ` · listen: ${rec}.mp3` : '');
return [
  { json: { to: CFG.NICOLE, body, from: s(b.To), sid_account: CFG.TWILIO_SID, log: { url: CFG.SUPA_URL + '/rest/v1/dne_missed_calls?call_sid=eq.' + encodeURIComponent(sid), apikey: CFG.SUPA_KEY, payload: { voicemail_text: text, recording_url: rec || null } } } },
  { json: { to: CFG.NICK, body, from: s(b.To), sid_account: CFG.TWILIO_SID } },
];
